package com.hms.billing;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/subscription") public class SubscriptionController {private final TenantRepository tenants;private final TenantSubscriptionRepository subscriptions;public SubscriptionController(TenantRepository t,TenantSubscriptionRepository s){tenants=t;subscriptions=s;} @GetMapping public TenantSubscription get(@PathVariable String tenantSlug){return subscriptions.findById(tenant(tenantSlug)).orElseThrow(()->new IllegalArgumentException("Subscription not configured"));} @PutMapping public TenantSubscription update(@PathVariable String tenantSlug,@Valid @RequestBody UpdateSubscriptionRequest r){UUID id=tenant(tenantSlug);TenantSubscription s=subscriptions.findById(id).orElseGet(()->new TenantSubscription(id,r));s.apply(r);return subscriptions.save(s);} private UUID tenant(String slug){return tenants.findBySlug(slug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(slug));}}
